css:
.silverwave-sim-container {
    padding: 28px;
    background: linear-gradient(180deg, #faf6f0 0%, #f3ebe0 100%);
    min-height: 100vh;
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    color: #2a1f2d;
}

.silverwave-sim-header {
    background: linear-gradient(135deg, #6b2737 0%, #4a1a26 100%);
    color: #faf6f0;
    border-radius: 16px;
    padding: 32px 36px;
    margin-bottom: 24px;
    box-shadow: 0 8px 24px rgba(107, 39, 55, 0.22);
    border-left: 6px solid #c9a961;
}
.silverwave-sim-header h1 {
    margin: 0 0 6px 0;
    font-size: 1.7rem;
    font-weight: 700;
    letter-spacing: 0.01em;
    color: #faf6f0;
}
.silverwave-sim-subtitle {
    color: #e8d9b3;
    font-size: 0.95rem;
    letter-spacing: 0.02em;
    font-weight: 400;
}

.silverwave-sim-period-bar {
    background: #ffffff;
    border-radius: 10px;
    padding: 14px 22px;
    margin-bottom: 22px;
    box-shadow: 0 3px 10px rgba(0,0,0,0.04);
    display: flex;
    align-items: center;
    gap: 10px;
    flex-wrap: wrap;
    border-bottom: 3px solid #c9a961;
}
.silverwave-sim-period-bar span {
    font-weight: 600;
    color: #6b2737;
}
.silverwave-sim-round-title {
    margin-left: auto;
    color: #2a1f2d !important;
    font-style: italic;
    font-weight: 500 !important;
    font-size: 0.95rem;
}

.silverwave-sim-briefing {
    background: #fff9ed;
    border-left: 5px solid #c9a961;
    border-radius: 10px;
    padding: 22px 26px;
    margin-bottom: 28px;
    box-shadow: 0 4px 14px rgba(201, 169, 97, 0.16);
}
.silverwave-sim-briefing-title {
    font-size: 0.82rem;
    text-transform: uppercase;
    letter-spacing: 0.14em;
    font-weight: 700;
    color: #6b2737;
    margin-bottom: 10px;
}
.silverwave-sim-briefing-text {
    font-size: 1rem;
    line-height: 1.65;
    color: #2a1f2d;
}

.silverwave-sim-kpi-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
    gap: 18px;
    margin-bottom: 28px;
}
.silverwave-sim-kpi-card {
    background: #ffffff;
    border-radius: 14px;
    padding: 22px 20px;
    box-shadow: 0 4px 14px rgba(0,0,0,0.06);
    position: relative;
    overflow: hidden;
    transition: transform 0.2s ease, box-shadow 0.2s ease;
}
.silverwave-sim-kpi-card:hover {
    transform: translateY(-2px);
    box-shadow: 0 8px 22px rgba(0,0,0,0.1);
}
.silverwave-sim-kpi-card::before {
    content: '';
    position: absolute;
    top: 0; left: 0; right: 0;
    height: 4px;
}
.silverwave-sim-kpi-revenue::before { background: #6b2737; }
.silverwave-sim-kpi-ebitda::before { background: #c9a961; }
.silverwave-sim-kpi-quality::before { background: #7a9471; }
.silverwave-sim-kpi-nps::before { background: #3d5a80; }
.silverwave-sim-kpi-compliance::before { background: #c97b63; }
.silverwave-sim-kpi-brand::before { background: #8b5a82; }

.silverwave-sim-kpi-label {
    color: #6b6570;
    font-size: 0.76rem;
    text-transform: uppercase;
    letter-spacing: 0.12em;
    margin-bottom: 10px;
    font-weight: 600;
}
.silverwave-sim-kpi-value {
    font-size: 2rem;
    font-weight: 700;
    color: #2a1f2d;
    line-height: 1.1;
}

.silverwave-sim-controls {
    background: #ffffff;
    border-radius: 14px;
    padding: 28px 30px;
    margin-bottom: 28px;
    box-shadow: 0 6px 20px rgba(0,0,0,0.06);
    border-top: 4px solid #6b2737;
}
.silverwave-sim-controls h3 {
    font-size: 1.2rem;
    color: #6b2737;
    margin: 0 0 22px 0;
    font-weight: 700;
    letter-spacing: 0.02em;
}
.silverwave-sim-decision-row {
    margin-bottom: 22px;
}
.silverwave-sim-decision-row label {
    display: block;
    font-size: 0.94rem;
    font-weight: 600;
    color: #4a1a26;
    margin-bottom: 8px;
}
.silverwave-sim-controls input[type="number"],
.silverwave-sim-controls select {
    background: #faf6f0;
    border: 1.5px solid #d4c5a9;
    color: #2a1f2d;
    border-radius: 8px;
    padding: 11px 14px;
    width: 100%;
    font-size: 0.98rem;
    transition: border-color 0.2s ease, background 0.2s ease, box-shadow 0.2s ease;
    font-family: inherit;
}
.silverwave-sim-controls input[type="number"]:focus,
.silverwave-sim-controls select:focus {
    outline: none;
    border-color: #6b2737;
    background: #ffffff;
    box-shadow: 0 0 0 3px rgba(107, 39, 55, 0.14);
}
.silverwave-sim-controls select option {
    background: #ffffff;
    color: #2a1f2d;
}
.silverwave-sim-hint {
    font-size: 0.82rem;
    color: #6b6570;
    margin-top: 7px;
    font-style: italic;
    line-height: 1.45;
}
.silverwave-sim-button-row {
    display: flex;
    gap: 12px;
    flex-wrap: wrap;
    margin-top: 12px;
}
.silverwave-sim-button-row .btn-primary {
    background: linear-gradient(135deg, #6b2737, #8b3547);
    border: none;
    color: #ffffff;
    padding: 12px 28px;
    border-radius: 8px;
    font-weight: 600;
    font-size: 0.98rem;
    letter-spacing: 0.02em;
    transition: all 0.2s ease;
    box-shadow: 0 4px 12px rgba(107, 39, 55, 0.22);
}
.silverwave-sim-button-row .btn-primary:hover {
    transform: translateY(-1px);
    box-shadow: 0 6px 18px rgba(107, 39, 55, 0.32);
}
.silverwave-sim-button-row .btn-outline-secondary {
    background: transparent;
    border: 1.5px solid #6b6570;
    color: #6b6570;
    padding: 10px 18px;
    border-radius: 8px;
    font-weight: 500;
    transition: all 0.2s ease;
}
.silverwave-sim-button-row .btn-outline-secondary:hover {
    background: #6b6570;
    color: #ffffff;
}

.silverwave-sim-history,
.silverwave-sim-chart-panel {
    background: #ffffff;
    border-radius: 14px;
    padding: 26px 28px;
    margin-bottom: 24px;
    box-shadow: 0 6px 18px rgba(0,0,0,0.06);
}
.silverwave-sim-history h3,
.silverwave-sim-chart-panel h3 {
    font-size: 1.1rem;
    color: #6b2737;
    margin: 0 0 18px 0;
    font-weight: 700;
}
.silverwave-sim-history table {
    font-size: 0.92rem;
    color: #2a1f2d;
    margin-bottom: 0;
}
.silverwave-sim-history table thead th {
    background: #f3ebe0;
    color: #4a1a26;
    font-weight: 700;
    border-top: none;
    border-bottom: 2px solid #c9a961;
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    padding: 10px 8px;
}
.silverwave-sim-history table tbody tr {
    background: #ffffff;
}
.silverwave-sim-history table tbody tr:nth-child(even) {
    background: #faf6f0;
}
.silverwave-sim-history table tbody td {
    padding: 10px 8px;
    border-top: 1px solid #f3ebe0;
}

.silverwave-sim-chart-wrapper {
    position: relative;
    height: 340px;
}

@media (max-width: 768px) {
    .silverwave-sim-container {
        padding: 16px;
    }
    .silverwave-sim-header {
        padding: 22px 20px;
    }
    .silverwave-sim-header h1 {
        font-size: 1.35rem;
    }
    .silverwave-sim-kpi-grid {
        grid-template-columns: repeat(2, 1fr);
        gap: 12px;
    }
    .silverwave-sim-kpi-value {
        font-size: 1.5rem;
    }
    .silverwave-sim-kpi-card {
        padding: 16px 14px;
    }
    .silverwave-sim-controls,
    .silverwave-sim-history,
    .silverwave-sim-chart-panel {
        padding: 18px;
    }
    .silverwave-sim-chart-wrapper {
        height: 280px;
    }
    .silverwave-sim-round-title {
        margin-left: 0;
        width: 100%;
    }
}

