        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    revenue:        380.0,
                    ebitdaMargin:   18.0,
                    cash:           45.0,
                    quality:        72,
                    nps:            68,
                    compliance:     80,
                    brand:          75,
                    marketShare:    2.1,
                    revenueHistory:    [],
                    ebitdaHistory:     [],
                    qualityHistory:    [],
                    npsHistory:        [],
                    complianceHistory: [],
                    brandHistory:      []
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    strategy:   'balanced',
                    investment: 6,
                    focus:      50
                };
            }
            this._updateRoundUI(state);
        }

        _currentLang() {
            try {
                if (window.mySimulation && window.mySimulation.currentLanguage) {
                    return window.mySimulation.currentLanguage === 'es' ? 'es' : 'en';
                }
            } catch (e) {}
            var htmlLang = (document.documentElement.lang || '').toLowerCase();
            return htmlLang.indexOf('es') === 0 ? 'es' : 'en';
        }

        _updateRoundUI(state) {
            var lang = this._currentLang();
            var period = state && state.currentPeriod ? state.currentPeriod : 1;
            var idx = Math.min(Math.max(period - 1, 0), this.ROUNDS.length - 1);
            var round = this.ROUNDS[idx];

            var titleEl = document.getElementById('roundTitle');
            if (titleEl) titleEl.textContent = lang === 'es' ? round.titleEs : round.title;

            var briefingEl = document.getElementById('briefingText');
            if (briefingEl) briefingEl.innerHTML = lang === 'es' ? round.briefingEs : round.briefing;

            var strategyLabelEl = document.getElementById('strategyLabel');
            if (strategyLabelEl) strategyLabelEl.textContent = lang === 'es' ? round.strategyLabelEs : round.strategyLabel;

            var investmentLabelEl = document.getElementById('investmentLabel');
            if (investmentLabelEl) investmentLabelEl.textContent = lang === 'es' ? round.investmentLabelEs : round.investmentLabel;

            var focusLabelEl = document.getElementById('focusLabel');
            if (focusLabelEl) focusLabelEl.textContent = lang === 'es' ? round.focusLabelEs : round.focusLabel;

            var selectEl = document.getElementById('strategyInput');
            if (selectEl) {
                selectEl.innerHTML = '';
                var opts = lang === 'es' ? round.strategyOptionsEs : round.strategyOptions;
                for (var i = 0; i < opts.length; i++) {
                    var optEl = document.createElement('option');
                    optEl.value = opts[i].value;
                    optEl.textContent = opts[i].text;
                    selectEl.appendChild(optEl);
                }
                selectEl.value = opts[0].value;
            }

            var investmentEl = document.getElementById('investmentInput');
            if (investmentEl) {
                investmentEl.max = round.investmentMax;
                investmentEl.value = round.investmentDefault;
            }

            var focusEl = document.getElementById('focusInput');
            if (focusEl) {
                focusEl.value = 50;
            }
        }

        validateDecisions(decisions) {
            var strategyEl = document.getElementById('strategyInput');
            if (strategyEl) decisions.strategy = strategyEl.value;

            var investmentEl = document.getElementById('investmentInput');
            if (investmentEl) decisions.investment = parseFloat(investmentEl.value);

            var focusEl = document.getElementById('focusInput');
            if (focusEl) decisions.focus = parseFloat(focusEl.value);

            if (isNaN(decisions.investment) || decisions.investment < 0) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('investment_warning'), 'warning'
                );
                return false;
            }
            if (isNaN(decisions.focus) || decisions.focus < 0 || decisions.focus > 100) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('focus_warning'), 'warning'
                );
                return false;
            }
            if (!decisions.strategy) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('strategy_warning'), 'warning'
                );
                return false;
            }
            return true;
        }

        calculateResults(state) { var __lang=this._currentLang();
            var d = state.decisions;
            var ds = state.domainState;
            var period = state.currentPeriod;

            var revenueDelta = 0;
            var ebitdaDelta  = 0;
            var qualityDelta = 0;
            var npsDelta     = 0;
            var complianceDelta = 0;
            var brandDelta   = 0;
            var cashDelta    = -d.investment;
            var eventLog     = '';

            if (period === 1) {
                if (d.strategy === 'premium') {
                    revenueDelta += 2 + (d.focus / 100) * 1.5;
                    ebitdaDelta  += 1.5;
                    qualityDelta += 3;
                    brandDelta   += 6;
                } else if (d.strategy === 'balanced') {
                    revenueDelta += 4;
                    ebitdaDelta  += 0.5;
                    qualityDelta += 2;
                    brandDelta   += 3;
                } else if (d.strategy === 'inclusive') {
                    revenueDelta += 6 + (d.focus / 100) * 3;
                    ebitdaDelta  -= 1;
                    qualityDelta -= 1;
                    brandDelta   += 4;
                } else if (d.strategy === 'home_aging') {
                    revenueDelta += 5 + (d.focus / 100) * 2;
                    ebitdaDelta  += 0.3;
                    qualityDelta += 2;
                    brandDelta   += 3;
                }
                qualityDelta += d.investment * 0.6;
                ebitdaDelta  -= d.investment * 0.12;
                npsDelta     += qualityDelta * 0.4;
                eventLog = (__lang==="es"?`Evento: se observan lanzamientos piloto en los cuatro segmentos de cuidado de mayores. El crecimiento del mercado medio es más fuerte entre prospectos de vida asistida de 75–84 años.`:`Event: pilot launches observed across all four elder-care segments. Mid-market growth is strongest among 75–84 assisted-living prospects.`);
            } else if (period === 2) {
                if (d.strategy === 'premium_only') {
                    revenueDelta += 1;
                    ebitdaDelta  += 2;
                    brandDelta   += 2;
                    npsDelta     -= 3;
                } else if (d.strategy === 'tiered') {
                    revenueDelta += 3;
                    ebitdaDelta  += 1;
                    brandDelta   += 3;
                    npsDelta     += 2;
                } else if (d.strategy === 'inclusive_pricing') {
                    revenueDelta += 5;
                    ebitdaDelta  -= 1;
                    brandDelta   += 4;
                    npsDelta     += 5;
                } else if (d.strategy === 'subsidized') {
                    revenueDelta += 7;
                    ebitdaDelta  -= 2.5;
                    brandDelta   += 5;
                    npsDelta     += 6;
                    complianceDelta += 2;
                }
                var affordFactor = d.focus / 100;
                revenueDelta += affordFactor * 2.5;
                ebitdaDelta  -= affordFactor * 1.5;
                brandDelta   += affordFactor * 2;
                qualityDelta += d.investment * 0.15;
                npsDelta     += d.investment * 0.25;
                if (d.strategy === 'premium_only') {
                    revenueDelta -= 3;
                    ebitdaDelta  -= 0.8;
                    eventLog = (__lang==="es"?`Evento: el PIB se contrajo 3%. La demanda premium cayó ~15% — mantener solo premium dejó capacidad vacía.`:`Event: GDP contracted 3%. Premium demand fell ~15% — holding premium left capacity empty.`);
                } else {
                    eventLog = (__lang==="es"?`Evento: el PIB se contrajo 3%. La demanda accesible subió 10–15%; los paquetes y subsidios capturaron cuota.`:`Event: GDP contracted 3%. Affordable demand rose 10–15%; bundling and subsidies captured share.`);
                }
            } else if (period === 3) {
                qualityDelta += d.investment * 0.35;
                if (d.strategy === 'monitoring') {
                    qualityDelta += 3;
                    ebitdaDelta  += 1;
                    complianceDelta += 3;
                    brandDelta   += 2;
                } else if (d.strategy === 'telehealth') {
                    qualityDelta += 4;
                    revenueDelta += 2;
                    ebitdaDelta  += 0.5;
                    brandDelta   += 3;
                } else if (d.strategy === 'companion') {
                    qualityDelta += 2;
                    npsDelta     += 4;
                    brandDelta   += 4;
                    ebitdaDelta  -= 0.3;
                } else if (d.strategy === 'analytics') {
                    ebitdaDelta  += 2;
                    complianceDelta += 4;
                    qualityDelta += 1;
                }
                var wagePct = (d.focus / 100) * 20;
                qualityDelta += wagePct * 0.25;
                npsDelta     += wagePct * 0.2;
                ebitdaDelta  -= wagePct * 0.22;
                if (wagePct < 5) {
                    npsDelta   -= 2;
                    brandDelta -= 2;
                    qualityDelta -= 2;
                }
                eventLog = (__lang==="es"?`Evento: un competidor digital de cuidado en el hogar bajó precios ~30%. La adopción tecnológica y la retención de personal fueron variables decisivas.`:`Event: digital home-care entrant cut prices ~30%. Tech adoption and staff retention were decisive variables.`);
            } else if (period === 4) {
                var baseline = 18;
                if (d.strategy === 'exceed') {
                    if (d.investment >= 25) {
                        complianceDelta += 16;
                        brandDelta      += 8;
                        qualityDelta    += 5;
                        ebitdaDelta     -= 2.2;
                        eventLog = (__lang==="es"?`Evento: VidaPlena superó los estándares nacionales. El regulador nombró a VidaPlena como referente de calidad.`:`Event: VidaPlena exceeded national standards. Regulator named VidaPlena a quality benchmark.`);
                    } else {
                        complianceDelta += 6;
                        brandDelta      += 1;
                        qualityDelta    += 1;
                        ebitdaDelta     -= 1;
                        eventLog = (__lang==="es"?`Evento: la meta de superar estándares quedó subfinanciada. Se cumplió la normativa, pero el relato de líder en calidad no se materializó.`:`Event: aim to exceed was underfunded. Compliance met, but quality-leader narrative under-delivered.`);
                    }
                } else if (d.strategy === 'minimum') {
                    if (d.investment >= baseline) {
                        complianceDelta += 8;
                        ebitdaDelta     -= 0.8;
                        brandDelta      -= 2;
                        eventLog = (__lang==="es"?`Evento: se logró el cumplimiento mínimo en la fecha límite. Competidores con mejor cumplimiento ganaron cuota.`:`Event: minimum compliance achieved on deadline. Competitors with stronger compliance took share.`);
                    } else {
                        complianceDelta -= 18;
                        brandDelta      -= 10;
                        qualityDelta    -= 6;
                        revenueDelta    -= 6;
                        eventLog = (__lang==="es"?`Evento: la brecha de cumplimiento provocó cierres de instalaciones y advertencias de licencia. El impacto reputacional fue severo.`:`Event: compliance gap triggered facility closures and license warnings. Reputation impact severe.`);
                    }
                } else if (d.strategy === 'lobby') {
                    complianceDelta += d.investment >= 10 ? 4 : -6;
                    brandDelta      -= 3;
                    ebitdaDelta     += 0.8;
                    cashDelta       += 4;
                    eventLog = (__lang==="es"?`Evento: el cabildeo aseguró una prórroga limitada; aumentaron el escrutinio regulatorio y el escepticismo mediático.`:`Event: lobby secured a limited extension; regulator scrutiny and media skepticism rose.`);
                } else if (d.strategy === 'partial') {
                    if (d.investment >= 12) {
                        complianceDelta += 10;
                        ebitdaDelta     += 1;
                        revenueDelta    -= 4;
                        brandDelta      -= 1;
                        eventLog = (__lang==="es"?`Evento: se cerraron instalaciones subescala; el portafolio restante es conforme y generador de caja.`:`Event: sub-scale facilities closed; remaining portfolio is compliant and cash-generative.`);
                    } else {
                        complianceDelta += 2;
                        revenueDelta    -= 5;
                        brandDelta      -= 3;
                        eventLog = (__lang==="es"?`Evento: la salida parcial se ejecutó mal. Cumplimiento irregular, ingresos a la baja y personal inquieto.`:`Event: partial exit executed poorly. Compliance patchy, revenue down, staff unsettled.`);
                    }
                }
                var passThrough = d.focus / 100;
                revenueDelta += passThrough * 5;
                ebitdaDelta  += passThrough * 2.2;
                npsDelta     -= passThrough * 4;
                brandDelta   -= passThrough * 1.5;
            } else if (period === 5) {
                if (d.strategy === 'organic') {
                    revenueDelta += 3 + d.investment * 0.12;
                    qualityDelta += 2;
                    ebitdaDelta  += 0.5;
                    brandDelta   += 3;
                } else if (d.strategy === 'acquisition') {
                    revenueDelta += 8 + d.investment * 0.20;
                    qualityDelta -= 2;
                    ebitdaDelta  -= 1.2;
                    brandDelta   += 1;
                    complianceDelta -= 2;
                } else if (d.strategy === 'partnership') {
                    revenueDelta += 5 + d.investment * 0.14;
                    qualityDelta += 1;
                    ebitdaDelta  += 1.5;
                    brandDelta   += 4;
                    complianceDelta += 2;
                } else if (d.strategy === 'vertical') {
                    revenueDelta += 4 + d.investment * 0.12;
                    qualityDelta += 3;
                    ebitdaDelta  += 2;
                    brandDelta   += 5;
                }
                var expansion = d.focus / 100;
                revenueDelta += expansion * 4;
                ebitdaDelta  -= expansion * 1.5;
                brandDelta   += expansion * 1;
                complianceDelta -= expansion * 2;
                if (ds.compliance < 65 || ds.quality < 55) {
                    brandDelta  -= 4;
                    ebitdaDelta -= 1.5;
                    eventLog = (__lang==="es"?`Evento: las bases débiles de cumplimiento y calidad limitaron el potencial de crecimiento. Los nuevos mercados fueron más difíciles de lo esperado.`:`Event: weak compliance and quality foundations capped growth upside. New markets were harder than expected.`);
                } else {
                    eventLog = (__lang==="es"?`Evento: la consolidación del mercado se aceleró; las bases sólidas convirtieron el capital en cuota de mercado.`:`Event: market consolidation accelerated; strong foundations translated capital into market share.`);
                }
            }

            ds.revenue      = Math.max(180, ds.revenue + revenueDelta);
            ds.ebitdaMargin = Math.max(-5, Math.min(35, ds.ebitdaMargin + ebitdaDelta));
            ds.quality      = Math.max(0, Math.min(100, ds.quality + qualityDelta));
            ds.nps          = Math.max(0, Math.min(100, ds.nps + npsDelta));
            ds.compliance   = Math.max(0, Math.min(100, ds.compliance + complianceDelta));
            ds.brand        = Math.max(0, Math.min(100, ds.brand + brandDelta));

            var operatingCashIn = ds.revenue * (ds.ebitdaMargin / 100) * 0.12;
            ds.cash = ds.cash + cashDelta + operatingCashIn;

            ds.revenueHistory.push(Math.round(ds.revenue * 10) / 10);
            ds.ebitdaHistory.push(Math.round(ds.ebitdaMargin * 10) / 10);
            ds.qualityHistory.push(Math.round(ds.quality));
            ds.npsHistory.push(Math.round(ds.nps));
            ds.complianceHistory.push(Math.round(ds.compliance));
            ds.brandHistory.push(Math.round(ds.brand));

            // Platform score: the finalScore composite of getPerformanceSummary (native 0-100) over the rounds played so far, from the same rounded values.
            var mean = function(a) { var s = 0; for (var k = 0; k < a.length; k++) { s += a[k]; } return a.length ? s / a.length : 0; };
            var sc = this._composite(mean(ds.qualityHistory), mean(ds.complianceHistory), mean(ds.npsHistory), mean(ds.brandHistory),
                Math.round(ds.revenue) || 380, (Math.round(ds.ebitdaMargin * 10) / 10) || 18);
            state.domainState.performance = Object.assign({}, state.domainState.performance || {}, { overallScore: Math.max(0, Math.min(100, Math.round(sc.finalScore))) });

            var self = this;
            setTimeout(function() {
                self._updateRoundUI({ currentPeriod: period + 1 });
            }, 400);

            return {
                period:       period,
                strategy:     d.strategy,
                investment:   Math.round(d.investment * 10) / 10,
                focus:        d.focus,
                revenue:      Math.round(ds.revenue),
                ebitdaMargin: Math.round(ds.ebitdaMargin * 10) / 10,
                quality:      Math.round(ds.quality),
                nps:          Math.round(ds.nps),
                compliance:   Math.round(ds.compliance),
                brand:        Math.round(ds.brand),
                cash:         Math.round(ds.cash * 10) / 10,
                eventLog:     eventLog
            };
        }

        setupUI(uiManager) {
            uiManager.bind('currentDay', 'currentPeriod');
            uiManager.bind('maxPeriods', 'maxPeriods');
            uiManager.bind('revenueDisplay', 'domainState.revenue',
