        getHistoryTableConfig() {
            var self = this;
            var optionText = function(v) {
                var es = self._currentLang() === 'es';
                for (var i = 0; i < self.ROUNDS.length; i++) {
                    var opts = es ? self.ROUNDS[i].strategyOptionsEs : self.ROUNDS[i].strategyOptions;
                    for (var j = 0; j < opts.length; j++) { if (opts[j].value === v) return opts[j].text; }
