            return [
                { key: 'period',               label: 'Round',      i18nKey: 'col_round' },
                { key: 'results.strategy',     label: 'Strategy',   i18nKey: 'col_strategy', formatter: function(v) { return optionText(v); } },
                { key: 'results.investment',   label: 'Invest $M',  i18nKey: 'col_investment', formatter: function(v) { return '$' + v + 'M'; } },
                { key: 'results.focus',        label: 'Focus %',    i18nKey: 'col_focus',      formatter: function(v) { return v + '%'; } },
                { key: 'results.revenue',      label: 'Revenue',    i18nKey: 'col_revenue',    formatter: function(v) { return '$' + v + 'M'; } },
                { key: 'results.ebitdaMargin', label: 'EBITDA %',   i18nKey: 'col_ebitda',     formatter: function(v) { return v + '%'; } },
                { key: 'results.quality',      label: 'Quality',    i18nKey: 'col_quality' },
                { key: 'results.nps',          label: 'NPS',        i18nKey: 'col_nps' },
                { key: 'results.compliance',   label: 'Compliance', i18nKey: 'col_compliance' },
                { key: 'results.brand',        label: 'Brand',      i18nKey: 'col_brand' }
            ];
        }

        // Composite of the final verdict (same weights and clamps), shared by getPerformanceSummary and the per-round platform score.
        _composite(avgQuality, avgCompliance, avgNps, avgBrand, finalRevenue, finalEbitda) {
            var revenueGrowth = ((finalRevenue - 380) / 380) * 100;

            var financialScore  = Math.max(0, Math.min(100, 50 + revenueGrowth * 1.2 + (finalEbitda - 15) * 2));
            var operationalScore = Math.max(0, Math.min(100, (avgQuality + avgNps) / 2));
            var stakeholderScore = Math.max(0, Math.min(100, (avgCompliance + avgBrand) / 2));
            var strategicScore   = Math.max(0, Math.min(100, (avgQuality + avgBrand + avgCompliance) / 3));

            var finalScore = 0.4 * financialScore + 0.2 * operationalScore + 0.2 * stakeholderScore + 0.2 * strategicScore;
            return { revenueGrowth: revenueGrowth, financialScore: financialScore, operationalScore: operationalScore,
                     stakeholderScore: stakeholderScore, strategicScore: strategicScore, finalScore: finalScore };
        }

        getPerformanceSummary(history) {
            if (!history || !history.length) return {};
            var last = history[history.length - 1].results || {};
            var avg = function(key) {
                var sum = 0, n = 0;
                for (var i = 0; i < history.length; i++) {
                    var r = history[i].results;
                    if (r && typeof r[key] === 'number') { sum += r[key]; n++; }
                }
                return n ? sum / n : 0;
            };

            var avgQuality    = avg('quality');
            var avgCompliance = avg('compliance');
            var avgNps        = avg('nps');
            var avgBrand      = avg('brand');
            var finalRevenue  = last.revenue || 380;
            var finalEbitda   = last.ebitdaMargin || 18;

            var c = this._composite(avgQuality, avgCompliance, avgNps, avgBrand, finalRevenue, finalEbitda);
            var revenueGrowth    = c.revenueGrowth;
            var financialScore   = c.financialScore;
            var operationalScore = c.operationalScore;
            var stakeholderScore = c.stakeholderScore;
            var strategicScore   = c.strategicScore;
            var finalScore       = c.finalScore;

            var performance = window.mySimulation.t('perf_below');
            if (finalScore >= 85) performance = window.mySimulation.t('perf_excellent');
            else if (finalScore >= 70) performance = window.mySimulation.t('perf_competent');

            var insights = [];
            if (avgQuality > 75) insights.push(window.mySimulation.t('insight_quality_strong'));
            if (avgQuality < 55) insights.push(window.mySimulation.t('insight_quality_low'));
            if (avgCompliance < 65) insights.push(window.mySimulation.t('insight_compliance_gap'));
            if (revenueGrowth > 20) insights.push(window.mySimulation.t('insight_growth_high'));
            if (revenueGrowth < 0) insights.push(window.mySimulation.t('insight_revenue_down'));
            if (finalEbitda < 10) insights.push(window.mySimulation.t('insight_ebitda_low'));
            if (avgNps < 55) insights.push(window.mySimulation.t('insight_nps_weak'));
            if (insights.length === 0) insights.push(window.mySimulation.t('insight_balanced'));

            return {
                finalScore:      Math.round(finalScore),
                performance:     performance,
                totalRevenue:    finalRevenue,
                revenueGrowth:   Math.round(revenueGrowth * 10) / 10,
                avgQuality:      Math.round(avgQuality),
                avgCompliance:   Math.round(avgCompliance),
                avgNps:          Math.round(avgNps),
                avgBrand:        Math.round(avgBrand),
                financialScore:  Math.round(financialScore),
                operationalScore: Math.round(operationalScore),
                stakeholderScore: Math.round(stakeholderScore),
                strategicScore:   Math.round(strategicScore),
                insights:         insights
            };
        }

        getPresets() { return null; }

